#include "lora_tx_truth.hpp"
#include "signalscope/backend/dsp/recovery_export.hpp"
#include <bit>
#include <iostream>

using namespace signalscope;
using namespace signalscope::recovery::lora;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class F>void rejected(F action,const char* message){try{action();}catch(const std::exception&){return;}throw std::runtime_error(message);}
using namespace independent_lora_truth;
constexpr std::uint64_t origin=(1ULL<<54)+919;
std::vector<RecoveryValue> observed(const std::vector<unsigned>& symbols){std::vector<RecoveryValue> result;result.reserve(symbols.size());for(unsigned i=0;i<symbols.size();++i){RecoveryValue value;value.value=symbols[i];value.known=true;value.support={origin+8*i,8};value.metric=20;result.push_back(value);}return result;}
RecoveryResult evidence(std::vector<RecoveryValue> symbols,PacketOptions options){auto data=packet_evidence(symbols,options);auto source=std::make_shared<SignalWindow>();source->stream={8000,433012000,SampleFormat::cf32_le};source->segments.push_back({origin,std::vector<std::complex<float>>(symbols.size()*8,{.5f,0}),false});RecoveryResult result;static_cast<RecoveryData&>(result)=std::move(data);result.analysis=std::make_shared<WaveformAnalysis>(analyze_waveform(source));result.range={origin,source->sample_count()};result.provider_id="independent.lora-symbol-truth";result.resource_namespace="recovery-lora";result.method_version=1;validate_recovery(result);return result;}
void payloadMatches(const Packet& packet,const std::vector<unsigned>& expected){require(packet.header_usable && packet.bytes.size()>=expected.size(),"Packet did not establish its coding parameters or byte extent");for(unsigned i=0;i<expected.size();++i)require(packet.bytes[i].known && packet.bytes[i].value==expected[i],"Decoded payload differs from independent transmit truth");}
void publishedVector() {
    // Public interoperability vector, LoRaPHY.m v0.2.1, example at the class
    // declaration: https://github.com/jkadbear/LoRaPHY/blob/master/LoRaPHY.m
    const std::vector<unsigned> symbols{2541,1153,673,2397,1189,3509,41,3089,3237,3917,2729,2765,1417,2833,1389,801,3197,345,961,745,3101,297,1893,469};
    const std::vector<unsigned> payload{1,2,3,4,5,6,7,8,9};PacketOptions options;options.sf=12;options.low_data_rate=true;
    const auto packet=decode_symbols(observed(symbols),options);payloadMatches(packet,payload);require(packet.applied.payload_bytes==9 && packet.applied.coding_rate==4 && packet.applied.payload_crc && packet.bytes.size()==11 && packet.bytes[9].value==0xba && packet.bytes[10].value==0x2e && packet.payload_checksum==RecoveryCheckState::pass,"Public SF12 explicit-header/CRC vector did not interoperate");require(crc(payload)==0x2eba,"Independent CRC long division did not match the public on-air CRC");
    std::array<std::uint16_t,8> headerSymbols;for(unsigned i=0;i<8;++i)headerSymbols[i]=static_cast<std::uint16_t>(symbols[i]);const auto inspected=inspect_header(headerSymbols,12);require(inspected.parameters_known && inspected.payload_bytes==9 && inspected.coding_rate==4 && inspected.payload_crc && inspected.fec==RecoveryCheckState::pass && inspected.checksum==RecoveryCheckState::pass,"Fast header inspection changed the published header");
    const auto result=evidence(observed(symbols),options);require(result.frames[0].state==RecoveryFrameState::validated && result.stages[3].features.at("payload_observed_distance")==0,"Public vector was not strictly verified through generic evidence");
}
void allCodingModes() {
    const std::vector<unsigned> payload{0x41,0x4d,0x43,0,0xff,0x12,0xa5,0x5a};
    require(headerChecksum(3,2,2)==13,"Independent header checksum does not match the observed published layout");
    for(unsigned sf=7;sf<=12;++sf)for(unsigned rate=1;rate<=4;++rate)for(bool explicitHeader:{false,true})for(bool ldro:{false,true})for(bool withCrc:{false,true}) {
        PacketOptions options;options.sf=sf;options.coding_rate=rate;options.explicit_header=explicitHeader;options.low_data_rate=ldro;options.payload_crc=withCrc;options.payload_bytes=payload.size();
        const auto transmitted=encode(payload,options);const auto packet=decode_symbols(observed(transmitted.symbols),options);payloadMatches(packet,payload);require(!packet.truncated && packet.payload_fec==RecoveryCheckState::pass && packet.payload_checksum==(withCrc?RecoveryCheckState::pass:RecoveryCheckState::absent),"An SF/CR/header/LDRO/CRC coding mode lost its check state");
        const auto result=evidence(observed(transmitted.symbols),options);require(result.frames.size()==1 && result.frames[0].state==(withCrc?RecoveryFrameState::validated:RecoveryFrameState::candidate),"Absent PHY CRC was promoted to a verified payload");
        if(!explicitHeader)require(result.stages[5].features.at("header_checksum_state")==static_cast<unsigned>(RecoveryCheckState::not_applicable) && result.frames[0].checks[2].state==RecoveryCheckState::not_applicable,"Implicit mode reported a checksum failure for an absent header");
        const auto extent=[&](unsigned word){const unsigned initial=sf-2,columns=sf-2*ldro,width=4+rate;return word<initial?SignalSampleRange{origin,64}:SignalSampleRange{origin+8*(8+((word-initial)/columns)*width),8*width};};const auto low=extent(explicitHeader?5:0),high=extent(explicitHeader?6:1);const auto ranges=recovery_input_ranges(result,6,0,1);require(ranges.size()==1 && ranges.front().first==low.first && ranges.front().count==high.first+high.count-low.first,"Byte provenance did not reach the actual interleaved large source clock");
    }
    for(unsigned length:{0,1,2,3,255}){std::vector<unsigned> bytes(length);for(unsigned i=0;i<length;++i)bytes[i]=(i*37+19)&255;PacketOptions options;options.sf=7;options.low_data_rate=true;options.coding_rate=4;options.payload_crc=true;const auto tx=encode(bytes,options);const auto packet=decode_symbols(observed(tx.symbols),options);payloadMatches(packet,bytes);require(packet.payload_checksum==RecoveryCheckState::pass && packet.bytes.size()==length+2 && packet.workspace_payload_bytes()<=RecoveryBudget{}.workspace_payload_bytes,"Zero/short/maximum payload CRC or actual workspace failed");}
}
void corruptionAndErasures() {
    const std::vector<unsigned> payload{0x41,0x4d,0x43,0,0xff,0x12,0xa5,0x5a};PacketOptions options;options.payload_crc=true;options.sf=9;options.coding_rate=4;
    for(unsigned word=0;word<5;++word)for(unsigned bit=0;bit<8;++bit){auto tx=encode(payload,options);flip(tx,word,bit);const auto values=observed(tx.symbols);const auto packet=decode_symbols(values,options);payloadMatches(packet,payload);require(packet.words[word].received==(tx.words[word]^(1<<bit)) && packet.words[word].corrected && packet.words[word].decoded_word==tx.words[word] && packet.header.fec==RecoveryCheckState::pass,"Single-bit header correction lost raw evidence or fixed the wrong word");}
    for(unsigned rate:{3,4})for(unsigned bit=0;bit<4+rate;++bit){options.coding_rate=rate;auto tx=encode(payload,options);const auto word=options.sf;flip(tx,word,bit);const auto packet=decode_symbols(observed(tx.symbols),options);payloadMatches(packet,payload);require(packet.words[word].corrected && packet.words[word].distance==1 && packet.payload_checksum==RecoveryCheckState::pass,"Correctable payload codeword was not independently recovered");const auto result=evidence(observed(tx.symbols),options);require(result.sequences[2].values[word].value!=result.sequences[4].values[word].value && result.stages[3].features.at("payload_corrected_codewords")==1,"Correction overwrote the received codeword or disappeared from evidence");}
    options.coding_rate=1;auto weak=encode(payload,options);flip(weak,options.sf,4);const auto weakPacket=decode_symbols(observed(weak.symbols),options);payloadMatches(weakPacket,payload);require(weakPacket.payload_fec==RecoveryCheckState::fail && weakPacket.payload_checksum==RecoveryCheckState::pass,"A failed parity check disappeared because systematic bytes were unchanged");require(evidence(observed(weak.symbols),options).frames[0].state==RecoveryFrameState::candidate,"Parity-failed unchanged payload was promoted to a strict frame");
    options.coding_rate=4;auto doubleError=encode(payload,options);flip(doubleError,options.sf,0);flip(doubleError,options.sf,1);const auto damaged=decode_symbols(observed(doubleError.symbols),options);require(!damaged.words[options.sf].corrected && damaged.words[options.sf].check==RecoveryCheckState::fail && evidence(observed(doubleError.symbols),options).frames[0].state!=RecoveryFrameState::validated,"An ambiguous two-bit error was silently corrected into a strict frame");
    auto badCrc=encode(payload,options,true);require(evidence(observed(badCrc.symbols),options).frames[0].state==RecoveryFrameState::invalid,"Wrong PHY CRC validated a payload");auto badHeader=encode(payload,options,false,true);const auto failed=evidence(observed(badHeader.symbols),options);require(failed.frames.empty() && !failed.method.at("header_usable").get<bool>() && failed.stages[5].features.at("header_checksum_state")==static_cast<unsigned>(RecoveryCheckState::fail),"Invalid header parameters were trusted or its failure evidence hidden");
    const auto complete=encode(payload,options);auto erased=observed(complete.symbols);erased[6].known=false;erased[6].issue_key="issue.test_gap";const auto recovered=evidence(erased,options);require(recovered.frames[0].state==RecoveryFrameState::validated && recovered.stages[3].features.at("erasure_reconstructions").get<unsigned>()>0 && !recovered.sequences[0].values[6].known && !recovered.sequences[2].values[0].known && recovered.sequences[3].values[0].value==0xbf,"A recoverable erasure lost its known-bit mask or original gap");
    erased=observed(complete.symbols);erased.resize(erased.size()-3);const auto truncated=evidence(erased,options);require(truncated.frames[0].state==RecoveryFrameState::truncated && truncated.frames[0].checks[4].state==RecoveryCheckState::unknown && !truncated.frames[0].checks[4].evidence.contains("calculated"),"An incomplete packet became verified or acquired a fictional CRC value");
    options.correct_single_bit=false;auto detected=encode(payload,options);flip(detected,options.sf,0);const auto unchanged=decode_symbols(observed(detected.symbols),options);require(!unchanged.words[options.sf].corrected && unchanged.payload_fec==RecoveryCheckState::fail,"Detect-only policy silently enabled correction");
}
void limits() {
    PacketOptions options;options.payload_crc=true;const auto transmitted=encode({1,2,3,4},options);const auto input=observed(transmitted.symbols);
    for(unsigned which=0;which<6;++which){RecoveryBudget budget;if(which==0)budget.workspace_payload_bytes=1;if(which==1)budget.maximum_operations=1;if(which==2)budget.result_payload_bytes=1;if(which==3)budget.maximum_values=1;if(which==4)budget.maximum_links=1;if(which==5)budget.maximum_frames=0;rejected([&]{packet_evidence(input,options,budget);},"LoRa coding ignored a resource budget");}
    auto excessive=input;excessive.reserve(200000);rejected([&]{packet_evidence(std::move(excessive),options);},"LoRa evidence counted size instead of allocated symbol capacity");
    auto invalid=input;invalid[0].value=1u<<options.sf;rejected([&]{decode_symbols(invalid,options);},"An out-of-range LoRa symbol was accepted");options.sf=6;rejected([&]{decode_symbols(input,options);},"An unsupported spreading factor was accepted");options.sf=11;
    std::stop_source stop;stop.request_stop();rejected([&]{packet_evidence(input,options,{},stop.get_token());},"Canceled LoRa coding published a result");
}
}
int main(){try{publishedVector();allCodingModes();corruptionAndErasures();limits();std::cout<<"LoRa symbol coding: public SF12 vector, independent transmit truth, all SF7..12/CR4/5..8/header/LDRO/CRC modes, raw/corrected evidence, erasures, truncation, exact provenance and resource limits passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
